  "Focus minutes in the last 7 days": { es: "Minutos de concentración en los últimos 7 días", ar: "دقائق التركيز في آخر 7 أيام", zh: "最近 7 天的专注分钟", sw: "Dakika za umakini katika siku 7 zilizopita", sv: "Fokusminuter de senaste 7 dagarna", de: "Fokusminuten der letzten 7 Tage", pt: "Minutos de foco nos últimos 7 dias", fr: "Minutes de concentration sur les 7 derniers jours" },
  "How to use Focus Forge": { es: "Cómo usar Focus Forge", ar: "كيفية استخدام Focus Forge", zh: "如何使用 Focus Forge", sw: "Jinsi ya kutumia Focus Forge", sv: "Så använder du Focus Forge", de: "So nutzt du Focus Forge", pt: "Como usar o Focus Forge", fr: "Comment utiliser Focus Forge" },
  "Free Pomodoro focus timer with tasks and calm sounds — Focus Forge | MigaBuilder": { es: "Temporizador Pomodoro gratuito con tareas y sonidos relajantes — Focus Forge | MigaBuilder", ar: "مؤقت بومودورو مجاني مع مهام وأصوات هادئة — Focus Forge | MigaBuilder", zh: "免费番茄钟，带任务和舒缓音效 — Focus Forge | MigaBuilder", sw: "Kipima muda cha Pomodoro bure chenye kazi na sauti tulivu — Focus Forge | MigaBuilder", sv: "Gratis Pomodoro-timer med uppgifter och lugna ljud — Focus Forge | MigaBuilder", de: "Kostenloser Pomodoro-Fokustimer mit Aufgaben und ruhigen Klängen — Focus Forge | MigaBuilder", pt: "Timer de foco Pomodoro gratuito com tarefas e sons calmos — Focus Forge | MigaBuilder", fr: "Minuteur Pomodoro gratuit avec tâches et sons apaisants — Focus Forge | MigaBuilder" },
  "Short break": { es: "Pausa corta", ar: "استراحة قصيرة", zh: "短休息", sw: "Pumziko fupi", sv: "Kort paus", de: "Kurze Pause", pt: "Pausa curta", fr: "Pause courte" },
  "Long break": { es: "Pausa larga", ar: "استراحة طويلة", zh: "长休息", sw: "Pumziko refu", sv: "Lång paus", de: "Lange Pause", pt: "Pausa longa", fr: "Pause longue" },
  "▶ Resume": { es: "▶ Reanudar", ar: "▶ استئناف", zh: "▶ 继续", sw: "▶ Endelea", sv: "▶ Fortsätt", de: "▶ Fortsetzen", pt: "▶ Continuar", fr: "▶ Reprendre" },
  "Break": { es: "Pausa", ar: "استراحة", zh: "休息", sw: "Pumziko", sv: "Paus", de: "Pause", pt: "Pausa", fr: "Pause" },
  "Focus session done — time for a": { es: "Sesión terminada: es hora de una", ar: "انتهت جلسة التركيز — حان وقت", zh: "专注时段结束——该休息了：", sw: "Kipindi cha umakini kimeisha — ni wakati wa", sv: "Fokuspasset är klart — dags för en", de: "Fokus-Sitzung fertig — Zeit für eine", pt: "Sessão de foco concluída — hora de uma", fr: "Séance terminée — place à une" },
  "Break over — ready to focus?": { es: "Se acabó la pausa: ¿listo para concentrarte?", ar: "انتهت الاستراحة — مستعد للتركيز؟", zh: "休息结束——准备好专注了吗？", sw: "Pumziko limekwisha — uko tayari kuzingatia?", sv: "Pausen är slut — redo att fokusera?", de: "Pause vorbei — bereit für den Fokus?", pt: "Fim da pausa — pronto para focar?", fr: "Fin de la pause — prêt à vous concentrer ?" },
  "Notification": { es: "Notificación", ar: "إشعار", zh: "通知", sw: "Arifa", sv: "Avisering", de: "Benachrichtigung", pt: "Notificação", fr: "Notification" },
  "Alerts are blocked for this site in your browser settings.": { es: "Los avisos están bloqueados para este sitio en los ajustes del navegador.", ar: "التنبيهات محظورة لهذا الموقع في إعدادات متصفحك.", zh: "浏览器设置中已阻止此网站的提醒。", sw: "Arifa zimezuiwa kwa tovuti hii katika mipangilio ya kivinjari chako.", sv: "Aviseringar är blockerade för den här webbplatsen i webbläsarens inställningar.", de: "Benachrichtigungen sind für diese Website in deinen Browsereinstellungen blockiert.", pt: "Os alertas estão bloqueados para este site nas configurações do navegador.", fr: "Les alertes sont bloquées pour ce site dans les paramètres de votre navigateur." },
